# transformations generate rotations/reflections
S=shape
def transforms(S):
 out=[]
 for refl in [False,True]:
  for k in range(4):
   pts=[]
   for y,x in S:
    if refl:x=-x
    for _ in range(k): y,x=x,-y
    pts.append((y,x))
   my=min(y for y,x in pts); mx=min(x for y,x in pts)
   pts=tuple(sorted((y-my,x-mx) for y,x in pts))
   if pts not in out:out.append(pts)
 return out
Ts=transforms(S); print(Ts)
out=[r[:] for r in g]; hits=[]
for sh in Ts:
 h=max(y for y,x in sh)+1; w=max(x for y,x in sh)+1
 for i in range(15-h+1):
  for j in range(22-w+1):
   if all(g[i+y][j+x]==0 for y,x in sh):
    hits.append((i,j,sh))
    for y,x in sh:out[i+y][j+x]=4
print(len(hits)); print('\n'.join(' '.join(map(str,r)) for r in out))

